export const BODY: string = "\n<p>صورة WebP منزّلة من موقع إلكتروني غالبًا ما ترفض الفتح في التطبيق الذي تريد استخدامه. الحل تحويلها إلى JPG.</p>\n<p>الجزء الوحيد المعقد هو الشفافية. JPG لا يستطيع حفظ بكسلات شفافة، لذلك يجب ملؤها بلون تختاره.</p>\n<p>يأخذك هذا الدليل خطوة بخطوة، لتخرج أول تحويلة نظيفة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: افحص ما إذا كانت هناك شفافية</h2>\n<p>قبل أن تبدأ، افحص ما إذا كانت هناك شفافية: افتح WebP وتحقق مما إذا كانت له خلفية شفافة. إذا كان كذلك، فستحتاج إلى اختيار لون خلفية.</p>\n<p>إذا كانت الصورة مستطيلة كاملة دون شفافية، فالتحويل مباشر. لا حاجة إلى التفكير في لون الخلفية.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة WebP إلى JPG</h2>\n<p>افتح <a href=\"/ar/tahwil-webp-ila-jpg/\">أداة WebP إلى JPG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات WebP</h2>\n<p>ارفع ملفات WebP: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات WebP بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بإعدادات موحدة.</p>\n<h2 id=\"step-3-matte-colour\">الخطوة 3: اختر لون الخلفية</h2>\n<p>اختر لون الخلفية: أبيض لمعظم الحالات، وأسود للخلفيات الداكنة. اللون يملأ المناطق الشفافة في الصورة.</p>\n<p>إذا لم تكن متأكدًا، فاختر الأبيض. إنه الخيار الآمن لمعظم الوجهات، من البريد الإلكتروني إلى المواقع.</p>\n<h2 id=\"step-4-quality\">الخطوة 4: اضبط منزلق الجودة</h2>\n<p>اضبط منزلق الجودة: جودة 90 مناسبة لمعظم الصور، و85 للمشاركة اليومية. جودة 95 للصور المهمة التي تحتاج إلى أقصى حدة.</p>\n<p>لا تستخدم جودة أقل من 80 للصور فيها نصوص. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"step-5-convert-preview\">الخطوة 5: حوّل وراجع النتيجة</h2>\n<p>حوّل وراجع النتيجة: اضغط زر التحويل وقارن النتيجة بالأصل. تأكد من أن الألوان صحيحة والنص حاد ولون الخلفية مناسب.</p>\n<p>إذا بدت النتيجة جيدة، فهي جاهزة. وإذا كان لون الخلفية خاطئًا، فأعد التحويل بلون مختلف.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات JPG</h2>\n<p>نزّل ملفات JPG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات WebP.</li>\n<li>اختر لون الخلفية.</li>\n<li>اضبط الجودة.</li>\n<li>نزّل ملفات JPG.</li>\n</ol>\n<h2 id=\"converting-a-batch\">تحويل دفعة من التنزيلات</h2>\n<p>لتحويل دفعة من التنزيلات، ارفع كل الملفات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>سمِّ المجلد حسب المشروع بعد التنزيل. التنظيم الجيد يسهّل العثور على الصور لاحقًا.</p>\n<h2 id=\"white-background-trick\">كيف تحصل على خلفية بيضاء نقية؟</h2>\n<p>للحصول على خلفية بيضاء نقية، اختر لونًا أبيض نقيًا كلون تعبئة. تأكد من أن الشعار نفسه لا يحمل ظلًا رماديًا.</p>\n<p>إذا ظهرت الخلفية رمادية بعد التحويل، فأعد التحويل بلون أبيض نقي. بعض الأدوات تستخدم أبيض غير نقي افتراضيًا.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الملف الذي يفشل في التحويل قد يكون تالفًا، والألوان المتغيرة قد تعني نمط ألوان غير مدعوم.</p>\n<p>أعد التحويل من الملف الأصلي بإعدادات مختلفة. لا تعيد التحويل من النسخة المحوّلة، لأن كل جولة تضيف ضررًا.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الصور من معرضك. التحويل يعمل على الهاتف دون تثبيت أي تطبيق.</p>\n<p>للدفعات الكبيرة على الهاتف، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"converting-wallpapers\">تحويل خلفيات منزّلة</h2>\n<p>لتحويل خلفيات منزّلة، حوّلها إلى JPG قبل تعيينها كخلفية. معظم الهواتف والحواسيب تقبل JPG كخلفية دون مشاكل.</p>\n<p>استخدم جودة 90 للخلفيات. الخلفية تملأ الشاشة كاملة، والجودة العالية تمنع التشوهات المرئية.</p>\n<h2 id=\"webp-school-project\">تحويل WebP لمشروع مدرسي</h2>\n<p>لتحويل WebP لمشروع مدرسي، حوّلها إلى JPG قبل إدراجها في المستند. برامج المدرسة تقبل JPG دائمًا، بينما WebP قد يُرفض.</p>\n<p>تحقق من أن كل صورة في مشروعك تفتح بشكل صحيح قبل التسليم. التحويل المسبق يمنع مفاجآت يوم التسليم.</p>\n<h2 id=\"webp-for-cv\">تحويل WebP لسيرة ذاتية</h2>\n<p>لتحويل WebP لسيرة ذاتية، حوّل الصورة إلى JPG بجودة عالية. البوابات تقبل JPG دائمًا، بينما ترفض WebP غالبًا.</p>\n<p>تحقق من أبعاد الصورة المطلوبة أيضًا. بعض البوابات تطلب أبعادًا محددة بالإضافة إلى الصيغة.</p>\n<h2 id=\"webp-for-printer\">تحويل WebP لطابعة</h2>\n<p>لتحويل WebP لطابعة، حوّلها إلى JPG أولًا. معظم الطابعات وخدمات الطباعة لا تقبل WebP مباشرة.</p>\n<p>اطبع من ملف JPG المحوّل بجودة عالية. الطباعة تحتاج دقة كاملة، لذلك استخدم جودة 95 للصور التي ستطبعها.</p>\n<h2 id=\"webp-received-by-email\">تحويل WebP مستلم بالبريد الإلكتروني</h2>\n<p>لتحويل WebP مستلم بالبريد الإلكتروني، احفظ المرفق أولًا ثم ارفعه إلى الأداة. المرفقات المستلمة كـWebP قد لا تفتح في برامج البريد.</p>\n<p>حوّلها إلى JPG قبل إعادة إرسالها أو استخدامها. بهذا تضمن أن المستلم يستطيع فتحها دون مشاكل.</p>\n<h2 id=\"webp-for-family-album\">تحويل WebP لألبوم عائلي</h2>\n<p>لتحويل WebP لألبوم عائلي، حوّلها إلى JPG واحفظها في مجلد الألبوم. JPG يعمل في كل الأجهزة التي يستخدمها أفراد العائلة.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-webp-ila-jpg/\">الدليل الكامل لتحويل WebP إلى JPG</a> و<a href=\"/ar/blog/webp-ila-jpg-al-tawafuq/\">WebP إلى JPG والتوافق</a>، أو حوّل إلى PNG باستخدام <a href=\"/ar/tahwil-webp-ila-png/\">محول WebP إلى PNG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أحصل على خلفية بيضاء نقية خلف شعار محوّل؟","answer":"اختر لونًا أبيض نقيًا كلون تعبئة، وتأكد من أن الشعار نفسه لا يحمل ظلًا رماديًا. الخلفية البيضاء النقية تعطي نتيجة نظيفة."},{"question":"هل يمكنني تحويل ملفات WebP لا تحمل امتدادًا؟","answer":"نعم، يمكنك تحويل ملفات WebP التي لا تحمل امتدادًا. أعد تسميتها بإضافة .webp أولًا، أو ارفعها مباشرة إذا قبلتها الأداة."},{"question":"ما إعداد الجودة الذي أستخدمه للقطات WebP؟","answer":"جودة 90 مناسبة للقطات WebP: النص يبقى حادًا والملف أصغر بكثير. للقطات النصية لا تنزل عن 85."},{"question":"هل يمكنني تحويل كثير من تنزيلات WebP إلى JPG دفعة واحدة؟","answer":"نعم، يمكنك تحويل كثير من تنزيلات WebP إلى JPG دفعة واحدة. ارفعها كلها وحوّلها بإعدادات موحدة ونزّلها كملف ZIP."},{"question":"هل سيفتح ملف JPG المحوّل في وورد وباوربوينت؟","answer":"نعم، ملف JPG المحوّل يفتح في وورد وباوربوينت وكل برامج أوفيس. JPG هو العيار العالمي في برامج العمل."},{"question":"هل يعمل تحويل WebP إلى JPG دون اتصال بالإنترنت؟","answer":"نعم، التحويل يعمل بالكامل في متصفحك دون اتصال بالخادم. بعد تحميل الصفحة، يعمل كل شيء دون إنترنت."}];
